<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=post_int('id');if(post('action')==='delete'){try{$pdo->prepare('DELETE FROM department WHERE department_id=?')->execute([$id]);flash('success','Department deleted.');}catch(Throwable $e){flash('error','Department cannot be deleted while it is used by an employee.');}}redirect('departments.php');}
$rows=$pdo->query('SELECT * FROM department ORDER BY department_id')->fetchAll();page_header('Departments','departments');?>
<div class="page-head"><h1>Departments</h1><a class="btn primary" href="department_form.php">Add Department</a></div><section class="card table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Budget</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['department_id']?></td><td><?=e($r['department_name'])?></td><td><?=money($r['department_budget'])?></td><td class="actions"><a href="department_form.php?id=<?=$r['department_id']?>">Edit</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['department_id']?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?></tbody></table></section><?php page_footer();?>
